#include <bits/stdc++.h>
using namespace std;

void quickSort(vector<int>& a, int l, int r) {
    if (l >= r) return;
    int pivot = a[(l + r) >> 1], i = l, j = r;
    while (i <= j) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i <= j) {
            swap(a[i], a[j]);
            i++; j--;
        }
    }
    quickSort(a, l, j);
    quickSort(a, i, r);
}

int main() {
    vector<int> a = {5, 2, 9, 1, 7, 6};
    quickSort(a, 0, (int)a.size() - 1);
    for (int x : a) cout << x << ' '; // 1 2 5 6 7 9
    return 0;
}

