function debounce(fn, delay = 300) {
  let timer = null
  return function (...args) {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      fn.apply(this, args)
      timer = null
    }, delay)
  }
}

// 验证：只打印最后一次
const log = debounce((x) => console.log('search:', x), 300)
log('a'); log('ab'); log('abc')

