#include <bits/stdc++.h>
using namespace std;

// 构建前缀和：pre[i] = a[0..i-1] 的和
vector<int> buildPrefix(const vector<int>& a) {
    int n = a.size();
    vector<int> pre(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        pre[i] = pre[i - 1] + a[i - 1];
    }
    return pre;
}

// 区间 [l, r] 和（闭区间，下标从 0 开始）
int rangeSum(const vector<int>& pre, int l, int r) {
    return pre[r + 1] - pre[l];
}

int main() {
    vector<int> a = {1, 2, 3, 4, 5};
    vector<int> pre = buildPrefix(a);
    cout << rangeSum(pre, 1, 3); // 2+3+4 = 9
    return 0;
}

