function throttle(fn, wait, options = {}) {
  let last = 0
  let timer = null

  return function (...args) {
    const now = Date.now()
    const remaining = wait - (now - last)

    if (remaining <= 0 || last === 0 && !options.leading) {
      if (timer) {
        clearTimeout(timer)
        timer = null
      }
      last = now
      fn.apply(this, args)
    } else if (!timer && options.trailing !== false) {
      timer = setTimeout(() => {
        timer = null
        last = options.leading ? Date.now() : 0
        fn.apply(this, args)
      }, remaining)
    }
  }
}

// 验证：滚动时至少执行一次，且结束时补执行
const onScroll = throttle(() => console.log('scroll'), 300)
window.addEventListener('scroll', onScroll)

